    /**
     * Method to retrieve the Certification via CertificationFetchOneSummary
     * @param 	summary CertificationFetchOneSummary 
     * @return 	CertificationFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Certification getCertification( CertificationFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "CertificationFetchOneSummary arg cannot be null" );
    	
    	Certification entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Certification
        	// --------------------------------------
        	CompletableFuture<Certification> futureEntity = queryGateway.query(new FindCertificationQuery( new LoadCertificationFilter( summary.getCertificationId() ) ), ResponseTypes.instanceOf(Certification.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Certification with id " + summary.getCertificationId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


